#include <stdlib.h>
#include <stddef.h>

typedef struct { int priority; long seq; void *payload; } entry_t;

/* entry_t* array, length n, min-heap on (priority, seq) */
static void sift_down(entry_t *a, size_t i, size_t n) {
    entry_t v = a[i];
    for (;;) {
        size_t l = 2 * i + 1, r = l + 1, c = l;
        if (l >= n) break;
        if (r < n && a[r].priority < a[l].priority) c = r;   /* smaller child */
        if (a[c].priority >= v.priority) break;
        a[i] = a[c]; i = c;
    }
    a[i] = v;
}

/* seq is a monotonic counter: the tie-breaker that makes equal priorities FIFO
   and stops the comparator from ever falling through to the payload */
